using ForensicEdu.Mobile.Controls;
using ForensicEdu.Mobile.Core.ViewModels;
namespace ForensicEdu.Mobile.Pages;
public sealed class ExamPage:AcademyPage
{
 private readonly string enrollmentId;private readonly ExamViewModel model;private Label timer=Ui.Text("10:00",28,true);private IDispatcherTimer? ticker;private int index;private bool starting;
 public ExamPage(IServiceProvider s,string id):base(s,"Evaluación"){enrollmentId=id;model=new(Api,s.GetRequiredService<TimeProvider>());}
 protected override async void OnAppearing(){base.OnAppearing();if(model.Session!=null){if(model.Result==null)ticker?.Start();return;}if(starting)return;starting=true;await Run(async()=>{await model.StartAsync(enrollmentId);Draw();ticker=Dispatcher.CreateTimer();ticker.Interval=TimeSpan.FromSeconds(1);ticker.Tick+=async(_,_)=>{var left=model.RemainingSeconds;timer.Text=$"{left/60:00}:{left%60:00}";if(left==0&&model.Result==null&&!State.IsBusy)await Submit();};ticker.Start();});starting=false;if(model.Session==null){Body.Clear();if(State.ErrorStatus==409){Body.Add(Ui.Text("Evaluación no disponible",22,true));await Run(async()=>{var enrollment=(await Api.GetAsync<List<ForensicEdu.Mobile.Core.Models.Enrollment>>("student/enrollments")).FirstOrDefault(x=>x.Id==enrollmentId);if(enrollment?.SecondAttemptAvailableAt is {} available&&available>DateTimeOffset.UtcNow)Body.Add(Ui.Text($"Tu siguiente intento estará disponible el {available.ToLocalTime():dd/MM/yyyy} a las {available.ToLocalTime():HH:mm} (hora local).",14));});}else Body.Add(Ui.Action("Volver a intentar",()=>{OnAppearing();return Task.CompletedTask;},true));Body.Add(Ui.Action("Volver al curso",async()=>{await Navigation.PopAsync();},true));}}
 protected override void OnDisappearing(){ticker?.Stop();base.OnDisappearing();}
 private void Draw(){Body.Clear();Header("EVALUACIÓN FINAL","Demuestra lo aprendido","El servidor controla el tiempo y la calificación.");if(model.Result!=null){ticker?.Stop();Body.Add(Ui.Card(Ui.Stack(Ui.Eyebrow(model.Result.Approved?"APROBADO":"EVALUACIÓN FINALIZADA"),Ui.Text($"{model.Result.Score}/20",44,true),Ui.Text(model.Result.Message),Ui.Action("Volver a mi curso",async()=>{await Navigation.PopAsync();})),true));return;}
  timer=Ui.Text("",28,true);var seconds=model.RemainingSeconds;timer.Text=$"{seconds/60:00}:{seconds%60:00}";var session=model.Session!;var question=session.Questions[index];Body.Add(Ui.Card(Ui.Row(Ui.Stack(Ui.Eyebrow($"INTENTO {session.AttemptNumber}"),Ui.Text($"Pregunta {index+1} de {session.Questions.Count}",13)),timer),true));Body.Add(Ui.Progress((index+1d)/session.Questions.Count));Body.Add(Ui.Card(Ui.Text(question.Question,22,true)));
  for(var i=0;i<question.Options.Count;i++){var choice=i;var chosen=model.Answers.GetValueOrDefault(question.Id,-1)==i;Body.Add(Ui.Action($"{(char)('A'+i)}. {question.Options[i]}"+(chosen?" ✓":""),()=>Run(async()=>{await model.ChooseAsync(question.Id,choice);Draw();}),!chosen));}
  if(index>0)Body.Add(Ui.Action("Anterior",()=>{index--;Draw();return Task.CompletedTask;},true));if(index<session.Questions.Count-1)Body.Add(Ui.Action("Siguiente  →",()=>{index++;Draw();return Task.CompletedTask;}));Body.Add(Ui.Action("Finalizar evaluación",async()=>{if(await DisplayAlertAsync("Enviar evaluación","¿Confirmas que deseas finalizar este intento?","Enviar","Revisar"))await Submit();},true));
 }
 private Task Submit()=>Run(async()=>{await model.SubmitAsync(enrollmentId,Session.User!.Id);Draw();});
}
